package io.knowledgebrain.activity;
import java.time.*;import java.util.*;import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;import io.knowledgebrain.contracts.learning.githubevidence.v1.*;
final class GitHubLearningActivity {
 static boolean kind(String k){return Set.of("GITHUB_EVIDENCE","GITHUB_EVIDENCE_SESSION").contains(k);}
 static String base(UUID space,UUID roadmap){return "/api/spaces/"+space+"/roadmaps/"+roadmap+"/github-evidence/";}
 static boolean target(ActivityEvent e){try{if(e.roadmapId()==null||e.nodeId()==null||e.sourceVersion()<1||e.planning()!=null||e.content()!=null||e.note()!=null||e.noteConcepts()!=null||e.metadata()!=null||e.noteLinks()!=null||e.noteAttachments()!=null||e.claim()!=null)return false;String prefix=base(e.spaceId(),e.roadmapId());if(e.kind().equals("GITHUB_EVIDENCE"))return e.targetPath().equals(prefix+e.aggregateId())&&e.aggregateType().equals("GitHubLearningEvidence")&&Set.of("ACTIVE","RETIRED").contains(e.state())&&Set.of("GitHubLearningEvidenceLinked","GitHubLearningEvidenceUpdated","GitHubLearningEvidenceRetired").contains(e.eventType())&&e.startedAt()==null&&e.endedAt()==null&&e.durationSeconds()==0;String tail=e.targetPath().substring(prefix.length());return e.targetPath().startsWith(prefix)&&tail.endsWith("/study-session")&&ActivityEvent.id(tail.substring(0,tail.length()-14))!=null&&e.aggregateType().equals("GitHubEvidenceStudySession")&&e.eventType().equals("GitHubEvidenceStudySessionChanged")&&Set.of("LINKED","UNLINKED").contains(e.state());}catch(RuntimeException error){return false;}}
 static String text(String value,int limit,boolean required){if(value==null||required&&value.isBlank()||value.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>limit||value.codePoints().anyMatch(c->Character.isISOControl(c)&&c!='\n'&&c!='\r'&&c!='\t'||c>=0xd800&&c<=0xdfff))throw ActivityEvent.invalid();return value;}
 static ActivityEvent decode(RoadmapEventEnvelopeV1 e,String kind)throws com.google.protobuf.InvalidProtocolBufferException{
  UUID event=ActivityEvent.id(e.getEventId()),space=ActivityEvent.id(e.getSpaceId()),actor=ActivityEvent.id(e.getActorId()),aggregate=ActivityEvent.id(e.getAggregateId());String at=Instant.ofEpochMilli(e.getOccurredAtEpochMillis()).toString();
  if(kind.equals("GITHUB_EVIDENCE")){var p=GitHubEvidenceChangedPayloadV1.parseFrom(e.getPayload());UUID roadmap=ActivityEvent.id(p.getRoadmapId()),node=ActivityEvent.id(p.getNodeId());ActivityEvent.id(p.getRevisionId());ActivityEvent.id(p.getRepositoryId());ActivityEvent.id(p.getCommitId());if(!aggregate.equals(ActivityEvent.id(p.getEvidenceId()))||!e.getAggregateType().equals("GitHubLearningEvidence")||!Set.of("GitHubLearningEvidenceLinked","GitHubLearningEvidenceUpdated","GitHubLearningEvidenceRetired").contains(e.getEventType())||!p.getVisibility().equals("PRIVATE")||!Set.of("ACTIVE","RETIRED").contains(p.getState())||p.getVersion()<1||p.getCommitVersion()!=1||!p.getRepositoryFullName().matches("[A-Za-z0-9-]{1,39}/[A-Za-z0-9_.-]{1,100}")||!p.getSha().matches("(?:[0-9a-f]{40}|[0-9a-f]{64})")||!p.getUrl().equals("https://github.com/"+p.getRepositoryFullName()+"/commit/"+p.getSha())||p.getSubject().codePointCount(0,p.getSubject().length())>500||p.getSubject().codePoints().anyMatch(Character::isISOControl)||!p.getAuthorLogin().isEmpty()&&!p.getAuthorLogin().matches("[A-Za-z0-9-]+(?:\\[bot\\])?"))throw ActivityEvent.invalid();Instant.parse(p.getCreatedAt());Instant.parse(p.getImportedAt());Instant.parse(p.getCommittedAt());if(Instant.parse(p.getUpdatedAt()).toEpochMilli()!=e.getOccurredAtEpochMillis())throw ActivityEvent.invalid();String nodeTitle=text(p.getNodeTitle(),800,true),memo=text(p.getMemo(),8192,false),detail="GitHub 커밋 시각: "+p.getCommittedAt()+"\n"+text(p.getSubject(),2000,false)+"\n"+memo+"\n개인 학습 근거이며 본인의 기여나 자동 완료를 뜻하지 않습니다.";return new ActivityEvent(event,space,actor,e.getTraceId(),at,kind,e.getEventType(),"GitHubLearningEvidence",aggregate,p.getVersion(),roadmap,node,p.getRepositoryFullName()+" · "+p.getSha().substring(0,12),nodeTitle,p.getState(),detail,null,null,0,base(space,roadmap)+aggregate,null,null,null,null,null,null,null,null);}
  var p=GitHubEvidenceSessionChangedPayloadV1.parseFrom(e.getPayload());UUID roadmap=ActivityEvent.id(p.getRoadmapId()),node=ActivityEvent.id(p.getNodeId()),evidence=ActivityEvent.id(p.getEvidenceId());ActivityEvent.id(p.getRevisionId());if(!aggregate.equals(ActivityEvent.id(p.getLinkId()))||!e.getAggregateType().equals("GitHubEvidenceStudySession")||!e.getEventType().equals("GitHubEvidenceStudySessionChanged")||!p.getEvidenceKind().equals("GITHUB")||!p.getVisibility().equals("PRIVATE")||p.getVersion()<1||!Set.of("LINKED","UNLINKED").contains(p.getState())||Instant.parse(p.getUpdatedAt()).toEpochMilli()!=e.getOccurredAtEpochMillis())throw ActivityEvent.invalid();Instant.parse(p.getCreatedAt());String nodeTitle=text(p.getNodeTitle(),800,true),start=null,end=null,detail="GitHub 근거 "+evidence;long seconds=0;if(p.getState().equals("LINKED")){ActivityEvent.id(p.getSessionId());text(p.getSessionNodeTitle(),800,true);if(p.getSessionVersion()<1)throw ActivityEvent.invalid();start=Instant.parse(p.getStartedAt()).toString();end=Instant.parse(p.getEndedAt()).toString();seconds=p.getDurationSeconds();if(seconds<1||seconds>86400||Duration.between(Instant.parse(start),Instant.parse(end)).getSeconds()!=seconds)throw ActivityEvent.invalid();detail+="\n학습 기록 v"+p.getSessionVersion()+" · "+p.getSessionNodeTitle();}else if(!p.getSessionId().isEmpty()||p.getSessionVersion()!=0||!p.getSessionNodeTitle().isEmpty()||!p.getStartedAt().isEmpty()||!p.getEndedAt().isEmpty()||p.getDurationSeconds()!=0)throw ActivityEvent.invalid();return new ActivityEvent(event,space,actor,e.getTraceId(),at,kind,e.getEventType(),"GitHubEvidenceStudySession",aggregate,p.getVersion(),roadmap,node,"GitHub 근거 학습 기록 연결",nodeTitle,p.getState(),detail,start,end,seconds,base(space,roadmap)+evidence+"/study-session",null,null,null,null,null,null,null,null);
 }
}
